const IND_META = {
  gdp_pc: { label: "GDP per capita", unit: "USD", fmt: (v) => "$" + fmt(v), color: "#C1873A" },
  life: { label: "Life expectancy", unit: "years", fmt: (v) => fmt(v) + " yrs", color: "#3C7A6D" },
  infant: { label: "Infant mortality", unit: "per 1,000 births", fmt: (v) => fmt(v), color: "#AD5346" },
  internet: { label: "Internet users", unit: "% of population", fmt: (v) => fmt(v) + "%", color: "#7C8FA6" },
  birth: { label: "Birth rate", unit: "per 1,000 people", fmt: (v) => fmt(v), color: "#8A6BAE" },
  death: { label: "Death rate", unit: "per 1,000 people", fmt: (v) => fmt(v), color: "#B08968" },
  electric: { label: "Electric power use", unit: "kWh per capita", fmt: (v) => fmt(v), color: "#4A7C8C" },
  popdensity: { label: "Population density", unit: "people / sq. km", fmt: (v) => fmt(v), color: "#6B8E4E" },
  unemployment: { label: "Unemployment", unit: "% of labor force", fmt: (v) => fmt(v) + "%", color: "#A65B7B" },
};
const INDICATORS = Object.keys(IND_META);

const INK = "#1B2430";
const PAPER = "#F6F4EE";
const GOLD = "#C1873A";
const TEAL = "#3C7A6D";
const ROSE = "#AD5346";
const LINE = "#DAD5C8";
const MUTE = "#6B7280";

function fmt(n) {
  if (n === null || n === undefined || isNaN(n)) return "—";
  if (Math.abs(n) >= 1000) return n.toLocaleString("en-US", { maximumFractionDigits: 0 });
  return n.toLocaleString("en-US", { maximumFractionDigits: 1 });
}

function Tag({ children }) {
  return (
    <span style={{
      fontFamily: "'IBM Plex Mono', monospace", fontSize: 11, color: MUTE,
      border: `1px solid ${LINE}`, borderRadius: 3, padding: "2px 7px", letterSpacing: 0.2,
    }}>
      {children}
    </span>
  );
}

function Pill({ active, onClick, children, small }) {
  return (
    <button
      onClick={onClick}
      style={{
        fontFamily: "'IBM Plex Sans', sans-serif", fontSize: small ? 12 : 13, cursor: "pointer",
        padding: small ? "5px 11px" : "8px 14px", borderRadius: 20,
        border: `1px solid ${active ? INK : LINE}`,
        background: active ? INK : "transparent", color: active ? PAPER : INK,
        whiteSpace: "nowrap", transition: "all 0.15s",
      }}
    >
      {children}
    </button>
  );
}

function CustomTooltip({ active, payload, label }) {
  if (!active || !payload || !payload.length) return null;
  return (
    <div style={{
      background: INK, color: PAPER, padding: "9px 13px", borderRadius: 4,
      fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 12.5, boxShadow: "0 4px 14px rgba(0,0,0,0.25)",
      maxWidth: 240,
    }}>
      {label !== undefined && <div style={{ opacity: 0.65, fontSize: 11, marginBottom: 4 }}>{label}</div>}
      {payload.map((p, i) => (
        <div key={i} style={{ display: "flex", gap: 8, alignItems: "center", marginTop: i ? 2 : 0 }}>
          {p.color && <span style={{ width: 7, height: 7, background: p.color, display: "inline-block", borderRadius: 2, flexShrink: 0 }} />}
          <span>{p.name ? p.name + ": " : ""}<strong>{typeof p.value === "number" ? fmt(p.value) : p.value}</strong></span>
        </div>
      ))}
    </div>
  );
}

/* ---------------------------------------------------------
   ROOT
--------------------------------------------------------- */
export default function FullDashboard() {
  const { countries, regions, incomes, indicatorCols, rows } = DATA;
  const idxOf = (col) => indicatorCols.indexOf(col);

  const [year, setYear] = useState(2017);
  const [indicator, setIndicator] = useState("gdp_pc");
  const [regionFilter, setRegionFilter] = useState("All");
  const [incomeFilter, setIncomeFilter] = useState("All");
  const [search, setSearch] = useState("");
  const [rankDir, setRankDir] = useState("top");
  const [trendCountries, setTrendCountries] = useState(["India", "China", "United States"]);
  const [trendSearch, setTrendSearch] = useState("");
  const [sortCol, setSortCol] = useState(indicator);
  const [sortDir, setSortDir] = useState("desc");
  const [page, setPage] = useState(0);

  const years = useMemo(() => {
    const s = new Set(rows.map((r) => r[3]));
    return Array.from(s).sort((a, b) => a - b);
  }, [rows]);
  const minYear = years[0], maxYear = years[years.length - 1];

  const indColIdx = idxOf(indicator);

  // rows for the selected year, respecting region/income filters
  const yearRows = useMemo(() => {
    return rows
      .filter((r) => r[3] === year)
      .filter((r) => regionFilter === "All" || regions[r[1]] === regionFilter)
      .filter((r) => incomeFilter === "All" || incomes[r[2]] === incomeFilter)
      .map((r) => ({
        country: countries[r[0]],
        region: regions[r[1]],
        income: incomes[r[2]],
        year: r[3],
        values: indicatorCols.reduce((acc, col, i) => { acc[col] = r[4 + i]; return acc; }, {}),
      }));
  }, [rows, year, regionFilter, incomeFilter]);

  // KPI stats for selected indicator + year + filters
  const stats = useMemo(() => {
    const vals = yearRows.map((r) => r.values[indicator]).filter((v) => v !== null && v !== undefined);
    if (!vals.length) return null;
    const avg = vals.reduce((a, b) => a + b, 0) / vals.length;
    const withCountry = yearRows.filter((r) => r.values[indicator] !== null && r.values[indicator] !== undefined);
    const maxRow = withCountry.reduce((a, b) => (a.values[indicator] > b.values[indicator] ? a : b));
    const minRow = withCountry.reduce((a, b) => (a.values[indicator] < b.values[indicator] ? a : b));
    return { avg, count: vals.length, maxRow, minRow };
  }, [yearRows, indicator]);

  // ranked bar data
  const ranked = useMemo(() => {
    const withVal = yearRows.filter((r) => r.values[indicator] !== null && r.values[indicator] !== undefined);
    const sorted = [...withVal].sort((a, b) =>
      rankDir === "top" ? b.values[indicator] - a.values[indicator] : a.values[indicator] - b.values[indicator]
    );
    return sorted.slice(0, 12).map((r) => ({ country: r.country, value: r.values[indicator], region: r.region }));
  }, [yearRows, indicator, rankDir]);

  // scatter: gdp_pc vs selected indicator (skip when indicator itself is gdp_pc -> use life instead)
  const scatterY = indicator === "gdp_pc" ? "life" : indicator;
  const scatterData = useMemo(() => {
    return yearRows
      .filter((r) => r.values.gdp_pc !== null && r.values[scatterY] !== null && r.values.gdp_pc !== undefined && r.values[scatterY] !== undefined)
      .map((r) => ({
        x: r.values.gdp_pc, y: r.values[scatterY], z: r.values.popdensity || 1,
        country: r.country, region: r.region,
      }));
  }, [yearRows, scatterY]);

  const regionColorMap = {
    "East Asia & Pacific": "#C1873A", "Europe & Central Asia": "#3C7A6D",
    "Latin America & Caribbean": "#AD5346", "Middle East & North Africa": "#8A6BAE",
    "North America": "#1B2430", "South Asia": "#4A7C8C", "Sub-Saharan Africa": "#6B8E4E",
  };

  // trend data across all years for selected countries
  const trendData = useMemo(() => {
    const byYear = {};
    for (const y of years) byYear[y] = { year: y };
    for (const cName of trendCountries) {
      const cIdx = countries.indexOf(cName);
      if (cIdx === -1) continue;
      for (const r of rows) {
        if (r[0] === cIdx) {
          byYear[r[3]][cName] = r[4 + indColIdx];
        }
      }
    }
    return years.map((y) => byYear[y]);
  }, [trendCountries, indicator, years]);

  const trendColors = [GOLD, TEAL, ROSE, "#7C8FA6", "#8A6BAE"];

  // data table rows
  const tableRows = useMemo(() => {
    let rs = yearRows.filter((r) => r.country.toLowerCase().includes(search.toLowerCase()));
    rs = [...rs].sort((a, b) => {
      let av, bv;
      if (sortCol === "country" || sortCol === "region" || sortCol === "income") {
        av = a[sortCol]; bv = b[sortCol];
        return sortDir === "asc" ? (av > bv ? 1 : -1) : (av < bv ? 1 : -1);
      }
      av = a.values[sortCol]; bv = b.values[sortCol];
      av = av === null || av === undefined ? -Infinity : av;
      bv = bv === null || bv === undefined ? -Infinity : bv;
      return sortDir === "asc" ? av - bv : bv - av;
    });
    return rs;
  }, [yearRows, search, sortCol, sortDir]);

  const pageSize = 12;
  const pageRows = tableRows.slice(page * pageSize, (page + 1) * pageSize);
  const pageCount = Math.max(1, Math.ceil(tableRows.length / pageSize));

  function toggleSort(col) {
    if (sortCol === col) setSortDir(sortDir === "asc" ? "desc" : "asc");
    else { setSortCol(col); setSortDir("desc"); }
    setPage(0);
  }

  const searchResults = trendSearch.length > 1
    ? countries.filter((c) => c.toLowerCase().includes(trendSearch.toLowerCase()) && !trendCountries.includes(c)).slice(0, 6)
    : [];

  const meta = IND_META[indicator];
  const scatterMeta = IND_META[scatterY];

  return (
    <div style={{ background: PAPER, minHeight: "100%" }}>
      <div style={{ maxWidth: 960, margin: "0 auto", padding: "36px 24px 60px", fontFamily: "'IBM Plex Sans', sans-serif" }}>

        {/* Header */}
        <div style={{ marginBottom: 26 }}>
          <div style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 11.5, color: GOLD, letterSpacing: 0.5, marginBottom: 8 }}>
            World Bank Development Indicators · Full Dataset
          </div>
          <h1 style={{ fontFamily: "'Source Serif 4', Georgia, serif", fontSize: 32, color: INK, margin: 0, lineHeight: 1.15 }}>
            Explore 211 countries, 1960–2018
          </h1>
          <p style={{ fontFamily: "'Source Serif 4', Georgia, serif", fontSize: 15, color: MUTE, maxWidth: 620, lineHeight: 1.6, margin: "10px 0 0" }}>
            Every country, every year, nine indicators. Pick a year and a measure, then rank, compare, and search.
          </p>
        </div>

        {/* Controls */}
        <div style={{ border: `1px solid ${LINE}`, borderRadius: 6, padding: "20px 22px", marginBottom: 30, background: "#FBFAF6" }}>

          <div style={{ marginBottom: 16 }}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8 }}>
              <span style={{ fontSize: 12.5, color: MUTE, fontFamily: "IBM Plex Mono" }}>YEAR</span>
              <span style={{ fontSize: 15, color: INK, fontFamily: "IBM Plex Mono", fontWeight: 600 }}>{year}</span>
            </div>
            <input
              type="range" min={minYear} max={maxYear} value={year}
              onChange={(e) => setYear(Number(e.target.value))}
              style={{ width: "100%", accentColor: GOLD }}
            />
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 10.5, color: MUTE, fontFamily: "IBM Plex Mono" }}>
              <span>{minYear}</span><span>{maxYear}</span>
            </div>
          </div>

          <div style={{ marginBottom: 14 }}>
            <div style={{ fontSize: 12.5, color: MUTE, fontFamily: "IBM Plex Mono", marginBottom: 8 }}>INDICATOR</div>
            <div style={{ display: "flex", gap: 7, flexWrap: "wrap" }}>
              {INDICATORS.map((k) => (
                <Pill key={k} active={indicator === k} onClick={() => { setIndicator(k); setSortCol(k); }} small>
                  {IND_META[k].label}
                </Pill>
              ))}
            </div>
          </div>

          <div style={{ display: "flex", gap: 30, flexWrap: "wrap" }}>
            <div>
              <div style={{ fontSize: 12.5, color: MUTE, fontFamily: "IBM Plex Mono", marginBottom: 8 }}>REGION</div>
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap", maxWidth: 480 }}>
                <Pill active={regionFilter === "All"} onClick={() => setRegionFilter("All")} small>All</Pill>
                {regions.map((r) => (
                  <Pill key={r} active={regionFilter === r} onClick={() => setRegionFilter(r)} small>{r}</Pill>
                ))}
              </div>
            </div>
          </div>

          <div style={{ marginTop: 14 }}>
            <div style={{ fontSize: 12.5, color: MUTE, fontFamily: "IBM Plex Mono", marginBottom: 8 }}>INCOME GROUP</div>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              <Pill active={incomeFilter === "All"} onClick={() => setIncomeFilter("All")} small>All</Pill>
              {incomes.map((inc) => (
                <Pill key={inc} active={incomeFilter === inc} onClick={() => setIncomeFilter(inc)} small>{inc}</Pill>
              ))}
            </div>
          </div>
        </div>

        {/* KPI strip */}
        {stats && (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 14, marginBottom: 36 }}>
            <div style={{ borderLeft: `3px solid ${GOLD}`, paddingLeft: 12 }}>
              <div style={{ fontSize: 11, color: MUTE, fontFamily: "IBM Plex Mono" }}>GLOBAL AVG</div>
              <div style={{ fontSize: 20, color: INK, fontFamily: "'Source Serif 4', Georgia, serif" }}>{meta.fmt(stats.avg)}</div>
            </div>
            <div style={{ borderLeft: `3px solid ${TEAL}`, paddingLeft: 12 }}>
              <div style={{ fontSize: 11, color: MUTE, fontFamily: "IBM Plex Mono" }}>HIGHEST</div>
              <div style={{ fontSize: 15, color: INK, fontFamily: "'Source Serif 4', Georgia, serif" }}>{stats.maxRow.country}</div>
              <div style={{ fontSize: 12, color: MUTE, fontFamily: "IBM Plex Mono" }}>{meta.fmt(stats.maxRow.values[indicator])}</div>
            </div>
            <div style={{ borderLeft: `3px solid ${ROSE}`, paddingLeft: 12 }}>
              <div style={{ fontSize: 11, color: MUTE, fontFamily: "IBM Plex Mono" }}>LOWEST</div>
              <div style={{ fontSize: 15, color: INK, fontFamily: "'Source Serif 4', Georgia, serif" }}>{stats.minRow.country}</div>
              <div style={{ fontSize: 12, color: MUTE, fontFamily: "IBM Plex Mono" }}>{meta.fmt(stats.minRow.values[indicator])}</div>
            </div>
            <div style={{ borderLeft: `3px solid ${MUTE}`, paddingLeft: 12 }}>
              <div style={{ fontSize: 11, color: MUTE, fontFamily: "IBM Plex Mono" }}>REPORTING</div>
              <div style={{ fontSize: 20, color: INK, fontFamily: "'Source Serif 4', Georgia, serif" }}>{stats.count}<span style={{ fontSize: 13, color: MUTE }}> countries</span></div>
            </div>
          </div>
        )}

        {/* Ranked bar */}
        <div style={{ marginBottom: 40 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 10 }}>
            <h3 style={{ fontFamily: "'Source Serif 4', Georgia, serif", fontSize: 20, color: INK, margin: 0 }}>
              {meta.label} — {rankDir === "top" ? "highest" : "lowest"} 12
            </h3>
            <div style={{ display: "flex", gap: 6 }}>
              <Pill active={rankDir === "top"} onClick={() => setRankDir("top")} small>Top</Pill>
              <Pill active={rankDir === "bottom"} onClick={() => setRankDir("bottom")} small>Bottom</Pill>
            </div>
          </div>
          <Tag>{meta.unit} · {year}{regionFilter !== "All" ? " · " + regionFilter : ""}{incomeFilter !== "All" ? " · " + incomeFilter : ""}</Tag>
          {ranked.length ? (
            <ResponsiveContainer width="100%" height={340}>
              <BarChart data={ranked} layout="vertical" margin={{ top: 14, right: 60, left: 10, bottom: 5 }}>
                <CartesianGrid horizontal={false} stroke={LINE} />
                <XAxis type="number" tick={{ fontFamily: "IBM Plex Sans", fontSize: 11, fill: MUTE }} axisLine={{ stroke: LINE }} tickLine={false} />
                <YAxis type="category" dataKey="country" width={150} tick={{ fontFamily: "IBM Plex Sans", fontSize: 12, fill: INK }} axisLine={{ stroke: LINE }} tickLine={false} />
                <Tooltip content={<CustomTooltip />} cursor={{ fill: "rgba(0,0,0,0.04)" }} />
                <Bar dataKey="value" radius={[0, 3, 3, 0]} fill={meta.color} barSize={16}>
                  <LabelList dataKey="value" position="right" formatter={meta.fmt} style={{ fontFamily: "IBM Plex Mono", fontSize: 11, fill: INK }} />
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          ) : <div style={{ padding: 30, color: MUTE, fontFamily: "IBM Plex Sans", fontSize: 13 }}>No data for this combination.</div>}
        </div>

        {/* Scatter */}
        <div style={{ marginBottom: 44 }}>
          <h3 style={{ fontFamily: "'Source Serif 4', Georgia, serif", fontSize: 20, color: INK, margin: "0 0 4px" }}>
            GDP per capita vs. {scatterMeta.label.toLowerCase()}
          </h3>
          <Tag>bubble size = population density · {year}{regionFilter !== "All" ? " · " + regionFilter : ""}</Tag>
          <ResponsiveContainer width="100%" height={360}>
            <ScatterChart margin={{ top: 20, right: 20, left: 0, bottom: 10 }}>
              <CartesianGrid stroke={LINE} />
              <XAxis type="number" dataKey="x" name="GDP per capita" tick={{ fontFamily: "IBM Plex Sans", fontSize: 11, fill: MUTE }} axisLine={{ stroke: LINE }} tickLine={false} label={{ value: "GDP per capita (USD)", position: "insideBottom", offset: -5, fontSize: 11, fill: MUTE }} />
              <YAxis type="number" dataKey="y" name={scatterMeta.label} tick={{ fontFamily: "IBM Plex Sans", fontSize: 11, fill: MUTE }} axisLine={{ stroke: LINE }} tickLine={false} label={{ value: scatterMeta.label, angle: -90, position: "insideLeft", fontSize: 11, fill: MUTE }} />
              <ZAxis type="number" dataKey="z" range={[20, 400]} />
              <Tooltip
                cursor={{ strokeDasharray: "3 3" }}
                content={({ active, payload }) => {
                  if (!active || !payload || !payload.length) return null;
                  const d = payload[0].payload;
                  return (
                    <div style={{ background: INK, color: PAPER, padding: "9px 13px", borderRadius: 4, fontFamily: "IBM Plex Sans", fontSize: 12.5 }}>
                      <div style={{ fontWeight: 600, marginBottom: 3 }}>{d.country}</div>
                      <div>GDP p.c.: ${fmt(d.x)}</div>
                      <div>{scatterMeta.label}: {fmt(d.y)}</div>
                    </div>
                  );
                }}
              />
              {regions.map((r) => (
                <Scatter key={r} name={r} data={scatterData.filter((d) => d.region === r)} fill={regionColorMap[r]} fillOpacity={0.7} />
              ))}
            </ScatterChart>
          </ResponsiveContainer>
          <div style={{ display: "flex", gap: 14, flexWrap: "wrap", marginTop: 6 }}>
            {regions.map((r) => (
              <div key={r} style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 11.5, color: MUTE, fontFamily: "IBM Plex Sans" }}>
                <span style={{ width: 8, height: 8, borderRadius: 4, background: regionColorMap[r], display: "inline-block" }} />
                {r}
              </div>
            ))}
          </div>
        </div>

        {/* Trend explorer */}
        <div style={{ marginBottom: 44 }}>
          <h3 style={{ fontFamily: "'Source Serif 4', Georgia, serif", fontSize: 20, color: INK, margin: "0 0 4px" }}>
            {meta.label} over time
          </h3>
          <Tag>{meta.unit} · {minYear}–{maxYear}</Tag>

          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", margin: "12px 0" }}>
            {trendCountries.map((c, i) => (
              <span key={c} style={{
                display: "flex", alignItems: "center", gap: 6, fontSize: 12.5, fontFamily: "IBM Plex Sans",
                border: `1px solid ${trendColors[i % trendColors.length]}`, color: trendColors[i % trendColors.length],
                borderRadius: 20, padding: "5px 6px 5px 12px",
              }}>
                {c}
                <button onClick={() => setTrendCountries(trendCountries.filter((x) => x !== c))}
                  style={{ background: "none", border: "none", cursor: "pointer", color: "inherit", fontSize: 14, lineHeight: 1, padding: "0 4px" }}>×</button>
              </span>
            ))}
          </div>

          <div style={{ position: "relative", maxWidth: 320, marginBottom: 16 }}>
            <input
              value={trendSearch}
              onChange={(e) => setTrendSearch(e.target.value)}
              placeholder="Add a country to compare…"
              style={{
                width: "100%", boxSizing: "border-box", padding: "8px 12px", borderRadius: 5,
                border: `1px solid ${LINE}`, fontFamily: "IBM Plex Sans", fontSize: 13, background: "#fff",
              }}
            />
            {searchResults.length > 0 && (
              <div style={{ position: "absolute", top: "100%", left: 0, right: 0, background: "#fff", border: `1px solid ${LINE}`, borderRadius: 5, marginTop: 4, zIndex: 5, boxShadow: "0 4px 14px rgba(0,0,0,0.1)" }}>
                {searchResults.map((c) => (
                  <div
                    key={c}
                    onClick={() => { if (trendCountries.length < 5) setTrendCountries([...trendCountries, c]); setTrendSearch(""); }}
                    style={{ padding: "8px 12px", cursor: "pointer", fontSize: 13, fontFamily: "IBM Plex Sans", color: INK, borderBottom: `1px solid ${LINE}` }}
                    onMouseDown={(e) => e.preventDefault()}
                  >
                    {c}
                  </div>
                ))}
              </div>
            )}
          </div>

          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={trendData} margin={{ top: 10, right: 20, left: 0, bottom: 5 }}>
              <CartesianGrid stroke={LINE} vertical={false} />
              <XAxis dataKey="year" tick={{ fontFamily: "IBM Plex Sans", fontSize: 11, fill: MUTE }} axisLine={{ stroke: LINE }} tickLine={false} />
              <YAxis tick={{ fontFamily: "IBM Plex Sans", fontSize: 11, fill: MUTE }} axisLine={false} tickLine={false} />
              <Tooltip content={<CustomTooltip />} />
              {trendCountries.map((c, i) => (
                <Line key={c} type="monotone" dataKey={c} stroke={trendColors[i % trendColors.length]} strokeWidth={2.5} dot={false} connectNulls activeDot={{ r: 4 }} />
              ))}
            </LineChart>
          </ResponsiveContainer>
        </div>

        {/* Data table */}
        <div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 10, flexWrap: "wrap", gap: 10 }}>
            <h3 style={{ fontFamily: "'Source Serif 4', Georgia, serif", fontSize: 20, color: INK, margin: 0 }}>
              All countries — {year}
            </h3>
            <input
              value={search}
              onChange={(e) => { setSearch(e.target.value); setPage(0); }}
              placeholder="Search country…"
              style={{ padding: "7px 12px", borderRadius: 5, border: `1px solid ${LINE}`, fontFamily: "IBM Plex Sans", fontSize: 13, width: 200, background: "#fff" }}
            />
          </div>
          <div style={{ overflowX: "auto", border: `1px solid ${LINE}`, borderRadius: 6 }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: "IBM Plex Sans", fontSize: 13 }}>
              <thead>
                <tr style={{ background: "#EFEBE0" }}>
                  {[["country", "Country"], ["region", "Region"], [indicator, meta.label]].map(([key, label]) => (
                    <th
                      key={key}
                      onClick={() => toggleSort(key)}
                      style={{ textAlign: key === indicator ? "right" : "left", padding: "9px 14px", cursor: "pointer", color: INK, fontWeight: 600, whiteSpace: "nowrap", userSelect: "none" }}
                    >
                      {label} {sortCol === key ? (sortDir === "asc" ? "↑" : "↓") : ""}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {pageRows.map((r, i) => (
                  <tr key={r.country} style={{ borderTop: `1px solid ${LINE}`, background: i % 2 ? "#FBFAF6" : "#fff" }}>
                    <td style={{ padding: "8px 14px", color: INK }}>{r.country}</td>
                    <td style={{ padding: "8px 14px", color: MUTE }}>{r.region}</td>
                    <td style={{ padding: "8px 14px", textAlign: "right", fontFamily: "IBM Plex Mono", color: INK }}>{meta.fmt(r.values[indicator])}</td>
                  </tr>
                ))}
                {!pageRows.length && (
                  <tr><td colSpan={3} style={{ padding: 20, textAlign: "center", color: MUTE }}>No countries match.</td></tr>
                )}
              </tbody>
            </table>
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 10, fontSize: 12.5, fontFamily: "IBM Plex Sans", color: MUTE }}>
            <span>{tableRows.length} countries</span>
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
              <button disabled={page === 0} onClick={() => setPage(page - 1)} style={{ border: `1px solid ${LINE}`, background: "#fff", borderRadius: 4, padding: "4px 10px", cursor: page === 0 ? "default" : "pointer", opacity: page === 0 ? 0.4 : 1 }}>Prev</button>
              <span>{page + 1} / {pageCount}</span>
              <button disabled={page >= pageCount - 1} onClick={() => setPage(page + 1)} style={{ border: `1px solid ${LINE}`, background: "#fff", borderRadius: 4, padding: "4px 10px", cursor: page >= pageCount - 1 ? "default" : "pointer", opacity: page >= pageCount - 1 ? 0.4 : 1 }}>Next</button>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
}
